#include <bits/stdc++.h>
using namespace std;
typedef pair<int, int> pii;
char mazeA[15][15], mazeB[15][15];
int dirA[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
int nodeIdx[65][15][15];
int maxFlowLimit[15][15];
int totalNodes = 1;

struct Edge {
  int u, v;
  long long cap, flow;
  Edge() {}
  Edge(int u, int v, long long cap): u(u), v(v), cap(cap), flow(0) {}
};

struct DinicSolver {
  int nodeCount;
  vector<Edge> edges;
  vector<vector<int>> adj;
  vector<int> level, ptr;

  DinicSolver(int N): nodeCount(N), edges(), adj(N), level(N), ptr(N) {}

  void addEdge(int u, int v, long long cap) {
    if (u != v) {
      edges.emplace_back(Edge(u, v, cap));
      adj[u].push_back(edges.size() - 1);
      edges.emplace_back(Edge(v, u, 0));
      adj[v].push_back(edges.size() - 1);
    }
  }

  bool buildLevelGraph(int S, int T) {
    queue<int> q({S});
    fill(level.begin(), level.end(), nodeCount + 1);
    level[S] = 0;
    while (!q.empty()) {
      int u = q.front(); q.pop();
      if (u == T) break;
      for (int e_idx: adj[u]) {
        Edge &e = edges[e_idx];
        if (e.flow < e.cap && level[e.v] > level[e.u] + 1) {
          level[e.v] = level[e.u] + 1;
          q.push(e.v);
        }
      }
    }
    return level[T] != nodeCount + 1;
  }

  long long pushFlow(int u, int T, long long flow = -1) {
    if (u == T || flow == 0) return flow;
    for (int &i = ptr[u]; i < (int)adj[u].size(); ++i) {
      Edge &e = edges[adj[u][i]];
      Edge &oe = edges[adj[u][i]^1];
      if (level[e.v] == level[e.u] + 1) {
        long long amt = e.cap - e.flow;
        if (flow != -1 && amt > flow) amt = flow;
        long long pushed = pushFlow(e.v, T, amt);
        if (pushed > 0) {
          e.flow += pushed;
          oe.flow -= pushed;
          return pushed;
        }
      }
    }
    return 0;
  }

  long long computeMaxFlow(int S, int T) {
    long long totalFlow = 0;
    while (buildLevelGraph(S, T)) {
      fill(ptr.begin(), ptr.end(), 0);
      while (long long flow = pushFlow(S, T))
        totalFlow += flow;
    }
    return totalFlow;
  }
};

int main() {
  memset(maxFlowLimit, -1, sizeof(maxFlowLimit));
  int n, t;
  scanf("%d%d", &n, &t);
  for (int i=1; i<=n; i++) {
    scanf("%s", mazeA[i]+1);
  }
  for (int i=0; i<=t+1; i++) {
    for (int j=1; j<=n; j++) {
      for (int k=1; k<=n; k++) {
        nodeIdx[i][j][k] = totalNodes++;
      }
    }
  }
  totalNodes++;
  for (int i=1; i<=n; i++) {
    scanf("%s", mazeB[i]+1);
  }
  queue<pii> q;
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (mazeA[i][j] == 'Z') {
        q.push({i, j});
        maxFlowLimit[i][j] = 0;
      }
    }
  }
  while (!q.empty()) {
    int y = q.front().first, x = q.front().second;
    q.pop();
    for (int i=0; i<4; i++) {
      int ny = y + dirA[i][0], nx = x + dirA[i][1];
      if (ny >= 1 && ny <= n && nx >= 1 && nx <= n && mazeA[ny][nx] != 'Y' && maxFlowLimit[ny][nx] == -1) {
        maxFlowLimit[ny][nx] = maxFlowLimit[y][x] + 1;
        q.push({ny, nx});
      }
    }
  }
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (maxFlowLimit[i][j] == -1) maxFlowLimit[i][j] = 1e9;
      if (maxFlowLimit[i][j] > t) maxFlowLimit[i][j] = 1e9;
    }
  }
  int s = 0, t_node = totalNodes - 1;
  DinicSolver flowSolver(totalNodes);
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (mazeA[i][j] >= '1' && mazeA[i][j] <= '9') {
        flowSolver.addEdge(s, nodeIdx[0][i][j], mazeA[i][j]-'0');
      }
    }
  }
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (mazeA[i][j] == 'Y' || mazeA[i][j] == 'Z') continue;
      for (int k=0; k<4; k++) {
        int ny = i + dirA[k][0], nx = j + dirA[k][1];
        if (ny >= 1 && ny <= n && nx >= 1 && nx <= n && mazeA[ny][nx] != 'Y' && mazeA[ny][nx] != 'Z') {
          for (int x=0; x<t; x++) {
            if (maxFlowLimit[ny][nx] >= x+1 && maxFlowLimit[i][j] > x) {
              flowSolver.addEdge(nodeIdx[x][i][j], nodeIdx[x+1][ny][nx], 1000);
            }
          }
        }
      }
    }
  }
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (mazeA[i][j] == 'Y' || mazeA[i][j] == 'Z') continue;
      for (int x=0; x<=t; x++) {
        if (mazeB[i][j] >= '1' && mazeB[i][j] <= '9') {
          flowSolver.addEdge(nodeIdx[x][i][j], nodeIdx[t+1][i][j], mazeB[i][j]-'0');
        }
      }
    }
  }
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (mazeA[i][j] == 'Y' || mazeA[i][j] == 'Z') continue;
      if (mazeB[i][j] >= '1' && mazeB[i][j] <= '9') {
        flowSolver.addEdge(nodeIdx[t+1][i][j], t_node, mazeB[i][j]-'0');
      }
    }
  }
  printf("%lld\n", flowSolver.getMaxFlow(s, t_node));
}
